// Help screenshots are resolved at runtime from this glob. A missing / renamed /
// retired image resolves to null -> the "screenshot pending" placeholder, so
// changes to the help capture set never break the Vite build.
const _images = import.meta.glob('../../../../../docs/help/v2/*', { eager: true, query: '?url', import: 'default' })
function _img(file) {
  if (!file) return null
  for (const k in _images) { if (k.endsWith('/' + file)) return _images[k] }
  return null
}

